body.script:
//
					const cfg      = document.getElementById('cfg').dataset;
					const ASSET    = cfg.asset;
					const REFRESH  = parseInt(cfg.refresh, 10) * 1000;
					// Set only by /<instrument>/4l (instrument_four_leg_gamma_chart)
					// — /4l/<asset> itself renders `instrument: False`, which QWeb's
					// t-att-* drops entirely, so cfg.instrument is undefined there
					// and INSTRUMENT stays null, same as before this route existed.
					// When set, this page has no "Expiry" dropdown at all (see
					// SELECTED_INSTRUMENT below and the template's own
					// t-if="not instrument") and fourLegGammaUrl() below
					// isolates directly to this one instrument.
					const INSTRUMENT = cfg.instrument || null;
					// "Timeframe" dropdown — same options as the Delta/Gamma/
					// Strike Gamma charts' own dropdown; was 15m by default,
					// then changed to 4h (matching those pages), then to 1d
					// per a further product decision (2026-08-19) — see
					// TF_WINDOW below for the per-timeframe visible-window
					// convention this page shares with those pages.
					let INTERVAL = '1d';
					// Coinbase spot, same symbol convention /aa/<asset> uses
					// (server-side _COINBASE_SYMBOL_MAP).
					const COINBASE_SYMBOL = { BTC: 'BTC-USD', ETH: 'ETH-USD' }[ASSET] || (ASSET + '-USD');
					document.getElementById('exchange-label').textContent = 'Coinbase · ' + COINBASE_SYMBOL;
					const klineUrl = (iv, limit) => '/api/klines-coinbase/' + ASSET + '?interval=' + iv + '&limit=' + limit;
					// "Expiry" dropdown — which expiry's trades feed the 4
					// gamma legs. Used to offer a fixed Nearest/Weekly/
					// Monthly option set (each resolved server-side via
					// four_leg_gamma_json's own ?expiry= mode strings) —
					// replaced per product decision with a dynamically
					// loaded list of every actually-active (non-expired)
					// instrument for ASSET (see loadExpiries() below,
					// sourced from /api/expiries/<asset>), so any real
					// expiry can be picked directly rather than only
					// through the weekly_expiry/monthly_expiry settings
					// indirection or the nearest/nearest_plus_1/
					// nearest_plus_2 ordinal family. Every option now
					// ISOLATES trades to that one instrument's own trades
					// via four_leg_gamma_json's own ?instrument= override
					// (same one /<instrument>/4l already uses) — there is
					// no cumulative "all expiries at once" option on this
					// dropdown (never was). SELECTED_INSTRUMENT holds the
					// currently chosen instrument string; NEAREST_INSTRUMENT
					// (the first, soonest-expiring entry loadExpiries()
					// receives) is tracked separately so refreshAvgGammaN1()
					// below can tell whether the current selection is the
					// nearest expiry without re-deriving it.
					let SELECTED_INSTRUMENT = null;
					let NEAREST_INSTRUMENT = null;
					// "Window" dropdown — trailing-hours trade window fed
					// into that same expiry's trades, independent of
					// SELECTED_INSTRUMENT. Choice set (1h/2h/3h/4h/5h/6h/7h/8h/12h/24h/All)
					// split out from /gt/<asset>'s own 12h/24h/48h.
					// 16h/20h/48h/72h were offered at one point and removed
					// per product decision; 3h/5h/7h were added later,
					// filling in the gaps left in the original
					// 1h/2h/4h/6h/8h/12h set; 24h and "All" (?hours=all,
					// skipping the trailing-hours trade filter entirely —
					// a number in every other case) were both re-added
					// afterwards per later product decisions;
					// 1h/2h/3h/4h/5h/6h/7h/8h were then removed in a
					// further round, leaving only 12h/24h/All, and the
					// default moved from 8h to "All" at that point; 8h was
					// then re-added per a still later product decision
					// (default stayed "All"), and 4h after that; the
					// default then moved back to 8h per a later product
					// decision (also cutting the routine per-poll cost of
					// the other 4 lines, since "All" meant every poll
					// scanned the selected instrument's entire trade
					// history — see FOUR_LEG_DEFAULT_WINDOW_HOURS), then to
					// 24h, then to 4h, then back to 24h per still later
					// product decisions; 1h/2h/3h/5h/6h/7h were then
					// re-added per a still later product decision, filling
					// this dropdown back out to every 1h step from 1h
					// through 8h plus 12h/24h/All. (Since relabeled to
					// 4h/8h/12h/1d-10d/All, given a "00:00 UTC" default
					// option, then given an "Auto (Time to Expiry)" option
					// which itself later became the default in place of
					// "00:00 UTC", then "All" became the default in "Auto"'s
					// place, then "Auto" was made the default again per a
					// still later product decision, then "All" was made the
					// default again per a further product decision — see
					// main.py's own FOUR_LEG_WINDOW_HOURS_CHOICES/
					// _auto_window_hours for the current full history.)
					let WINDOW_HOURS = 'all';
					// When WINDOW_HOURS === 'auto', this is the numeric hours
					// /api/four-leg-gamma actually resolved it to (its own
					// `window_hours` response field, via _auto_window_hours()
					// server-side — shrinks as the selected Expiry's own
					// settlement nears) — null until the first fetch resolves,
					// so windowLabel() can fall back to a plain "Auto" label
					// before that.
					let autoResolvedHours = null;
					// INSTRUMENT (only set on /<instrument>/4l) takes priority
					// over SELECTED_INSTRUMENT — both ultimately resolve to
					// the same ?instrument= override server-side, just
					// sourced from the URL vs. this page's own dropdown.
					const fourLegGammaUrl = () =>
						'/api/four-leg-gamma/' + ASSET + '?instrument=' + (INSTRUMENT || SELECTED_INSTRUMENT) + '&hours=' + WINDOW_HOURS;
					// Same "Last trade:" footer field the Delta Chart uses —
					// a growing gap between this and "now" is the at-a-glance
					// signal that dankbit_ws has stalled (its DB connection
					// can die without crashing the container, silently
					// dropping every trade — see dankbit_ws_batch.py).
					const LAST_TRADE_URL = '/api/last-trade/' + ASSET;
					let   lastTradeTs = null;
					// Trade count for the currently selected Window/Expiry —
					// same `trade_count` field /api/four-leg-gamma already
					// returns (len(trades) over the resolved instrument's
					// domain), just not previously surfaced on this page.
					// null until the first refreshFourLegGamma() resolves.
					let   tradeCount = null;

					// Shown in real UTC (not a browser-local shift) — this is a
					// staleness check against server time, not a chart position.
					function formatLastTradeTs(iso) {
						if (!iso) return null;
						return new Date(iso).toLocaleString('de-DE', {
							timeZone: 'UTC',
							year: 'numeric', month: '2-digit', day: '2-digit',
							hour: '2-digit', minute: '2-digit', second: '2-digit',
						}) + ' UTC';
					}

					// Same browser-local-timezone shift every other TV chart page
					// in this addon applies — Lightweight Charts always renders
					// epoch seconds as UTC wall-clock time, so every timestamp fed
					// into the chart is pre-shifted by the viewer's own current
					// UTC offset first.
					const tzOffset = (() => {
						let zone;
						try {
							zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
						} catch (e) {
							return 0;
						}
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }

					// "Settings" button/dialog (see openSettingsModal() below,
					// after Ruler) — user-pickable colors for this page's own
					// 4 gamma-leg lines, persisted per-browser to localStorage
					// under a key completely separate from the Delta Chart's
					// own 'dankbit_chart_colors' (dankbit_templates.xml) — the
					// two pages' color settings are deliberately independent,
					// not shared/synced, since they're maintained by different
					// people (Delta Chart: Thales's dev; this page: dankbit's
					// own). No line-style picker (unlike the Delta Chart's own
					// modal) since these 4 lines are always solid
					// createPriceLine()s. Defaults match this page's original
					// fixed colors (LC/LP black, SC/SP orange) — no longer
					// tied to DARK_MODE the way the old axisBlack()-based LC/LP
					// color was, same as every other user-configurable color
					// elsewhere in this addon (e.g. the Delta Chart's own Bands/
					// Smart Liquidity colors, which are likewise fixed once
					// chosen rather than swapping with the theme).
					const COLOR_STORAGE_KEY = 'dankbit_4l_chart_colors';
					const DEFAULT_COLORS = { bcg: '#000000', bpg: '#000000', scg: '#fb8c00', spg: '#fb8c00' };
					let chartColors = Object.assign({}, DEFAULT_COLORS);
					try {
						const savedColors = JSON.parse(localStorage.getItem(COLOR_STORAGE_KEY) || '{}');
						Object.keys(DEFAULT_COLORS).forEach(key => {
							if (savedColors[key]) chartColors[key] = savedColors[key];
						});
					} catch (e) { /* malformed stored value — fall back to defaults */ }
					// Average of the 4 gamma legs' own price levels — fixed
					// light violet (dashed line, see avgGammaPriceLine
					// below), same "gamma" color association this addon
					// uses elsewhere (the Zones page's violet Gamma section
					// header, the Delta Chart's own dashed violet Gamma Band
					// line) — not part of the "Chart Appearance" color
					// picker above (that modal only covers the 4 raw
					// BCG/BPG/SCG/SPG lines).
					const AVG_GAMMA_COLOR = '#c9a0dc';
					// Nearest+1 expiry's own 4-leg gamma average — drawn
					// ONLY while the "Expiry" dropdown is on "Nearest", as
					// a forward-looking reference for what's coming up
					// right after the currently-selected expiry (see
					// refreshAvgGammaN1() below). Computed over Nearest+1's
					// FULL trade history (?hours=all), independent of the
					// page's own Window selection, so it stays a stable
					// reference rather than thinning out/disappearing along
					// with a short trailing window. Darker violet + a
					// dotted style (vs. the primary AVG line's dashed light
					// violet) so the two stay visually distinguishable when
					// both are shown at once.
					const AVG_GAMMA_N1_COLOR = '#6a1b9a';

					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC',
								month: 'short', day: 'numeric',
								hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					window.addEventListener('resize', () => {
						chart.resize(window.innerWidth, window.innerHeight);
					});

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					// Invisible helper series solely to extend the shared time
					// axis past the last real candle, same mechanism the Delta
					// Chart's own futureAxisSeries uses (dankbit_templates.xml)
					// — candlestick setData() silently drops OHLC-less
					// "whitespace" points, so a real, fully-valued (if
					// invisible) line series is used instead; all series on a
					// chart share one time scale, so its future points extend
					// the same axis the candlesticks and the 4 gamma price
					// lines are drawn on, leaving room to see those lines
					// extend forward instead of ending flush at the last bar.
					const futureAxisSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					// The 4 gamma "lines" are horizontal reference lines at the
					// CURRENT (latest) value only — same createPriceLine()
					// pattern /gt/<asset> uses for its own gamma_band lines —
					// not a connected historical time series. Redrawn fresh
					// on every poll (REFRESH, from dankbit.refresh_interval),
					// each replacing its own previous line rather than
					// accumulating one per hour.
					let bcgPriceLine = null, bpgPriceLine = null, scgPriceLine = null, spgPriceLine = null, avgGammaPriceLine = null, avgGammaN1PriceLine = null;

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function lastTradeSuffix() {
						const label = formatLastTradeTs(lastTradeTs);
						return label ? '  ·  Last trade: ' + label : '';
					}

					// Same "N trades" convention the Delta Chart's own footer
					// uses (dankbit_templates.xml) — placed after the "Last
					// trade:" timestamp since it's the count feeding the
					// same Window that timestamp's own staleness matters for.
					function tradeCountSuffix() {
						return tradeCount !== null ? '  ·  ' + tradeCount + ' trades' : '';
					}

					// WINDOW_HOURS is the string 'all' when the "All" option is
					// selected (no trailing-hours trade filter at all — see
					// four_leg_gamma_json), the string 'midnight' when the
					// "00:00 UTC" option is selected (trades since the most
					// recent UTC midnight instead of a trailing-hours count),
					// the string 'auto' when the "Auto (Time to Expiry)"
					// option is selected (server picks the window, see
					// autoResolvedHours above), or a number otherwise. Values
					// >=24 (the 1d-10d dropdown entries — still raw hours
					// under the hood, see the window-select options) display
					// in days rather than hours, matching the dropdown's own
					// labels; 12h and below stay hour-labeled — hoursLabel()
					// applies that same day/hour split to autoResolvedHours
					// too, so "Auto" reads identically to picking that same
					// resolved value by hand.
					function hoursLabel(hours) {
						if (hours >= 24 && hours % 24 === 0) return (hours / 24) + 'd';
						return hours + 'h';
					}
					function windowLabel() {
						if (WINDOW_HOURS === 'all') return 'all trades';
						if (WINDOW_HOURS === 'midnight') return 'since 00:00 UTC';
						if (WINDOW_HOURS === 'auto') {
							return autoResolvedHours !== null
								? 'Auto → ' + hoursLabel(autoResolvedHours) + ' trailing window'
								: 'Auto trailing window';
						}
						return hoursLabel(WINDOW_HOURS) + ' trailing window';
					}

					function statusText() {
						return (INSTRUMENT || ASSET) + ' · Four Leg Gamma (' + windowLabel() + ', live)' + lastTradeSuffix() + tradeCountSuffix();
					}

					async function refreshLastTrade() {
						const data = await (await fetch(LAST_TRADE_URL)).json();
						lastTradeTs = data.last_trade_ts || null;
						setStatus(statusText());
					}

					function showSpinner() { document.getElementById('spinner').style.display = 'block'; }
					function hideSpinner() { document.getElementById('spinner').style.display = 'none'; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					let realCandles = [];

					// Same per-timeframe visible-window convention the
					// Delta/Gamma/Strike Gamma charts' own TF_WINDOW uses
					// (15m entry matches /gt/<asset>'s own TF_WINDOW).
					const TF_WINDOW = { '15m': 5, '1h': 30, '4h': 15, '1d': 365 };
					// Seconds per bar at each Timeframe — feeds the future-axis
					// tick spacing below (INTERVAL_SECONDS isn't needed
					// anywhere else on this page, unlike the Delta Chart's own
					// copy, which also uses it for its logical-range math).
					const INTERVAL_SECONDS = { '15m': 15 * 60, '1h': 3600, '4h': 4 * 3600, '1d': 86400 };
					// Same future-margin length as the Delta Chart's own
					// FUTURE_MARGIN_DAYS.
					const FUTURE_MARGIN_DAYS = 5;

					function applyVisibleRange() {
						if (!realCandles.length) return;
						const days = TF_WINDOW[INTERVAL] || 15;
						// Ends at the future-axis edge (see futureAxisSeries
						// above), not at the last real candle, so the visible
						// window always includes the future margin rather than
						// leaving it just off-screen to the right.
						const futureEdge = realCandles[realCandles.length - 1].time + FUTURE_MARGIN_DAYS * 86400;
						chart.timeScale().setVisibleRange({ from: futureEdge - days * 86400, to: futureEdge });
					}

					// Rebuilds both the real candle series and the invisible
					// future-axis extension together, so the two never fall
					// out of sync (same pattern the Delta Chart's own
					// rebuildSeriesData() uses).
					function rebuildSeriesData() {
						series.setData(realCandles);

						const intervalSec = INTERVAL_SECONDS[INTERVAL] || 3600;
						const lastClose = realCandles.length ? realCandles[realCandles.length - 1].close : 0;
						const lastTime = realCandles.length
							? realCandles[realCandles.length - 1].time
							: (Math.floor(Date.now() / 1000) + tzOffset);
						const count = Math.round(FUTURE_MARGIN_DAYS * 86400 / intervalSec);
						const futureTicks = [];
						for (let i = 1; i <= count; i++) {
							futureTicks.push({ time: lastTime + i * intervalSec, value: lastClose });
						}
						futureAxisSeries.setData(futureTicks);
					}

					function resetChartView() {
						chart.priceScale('right').applyOptions({ autoScale: true });
						applyVisibleRange();
					}

					const contextMenu = document.getElementById('context-menu');

					function hideContextMenu() {
						contextMenu.style.display = 'none';
					}

					function showContextMenu(x, y) {
						contextMenu.style.display = 'block';
						const maxX = window.innerWidth - contextMenu.offsetWidth - 4;
						const maxY = window.innerHeight - contextMenu.offsetHeight - 4;
						contextMenu.style.left = Math.min(x, maxX) + 'px';
						contextMenu.style.top = Math.min(y, maxY) + 'px';
					}

					function onResetChartViewClick() {
						resetChartView();
						hideContextMenu();
					}

					const chartContainerEl = document.getElementById('chart-container');
					chartContainerEl.addEventListener('contextmenu', e => {
						e.preventDefault();
						showContextMenu(e.clientX, e.clientY);
					});
					document.addEventListener('contextmenu', e => {
						if (!chartContainerEl.contains(e.target)) hideContextMenu();
					});
					document.addEventListener('click', hideContextMenu);
					window.addEventListener('resize', hideContextMenu);
					window.addEventListener('scroll', hideContextMenu, true);

					async function loadCandles() {
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						rebuildSeriesData();
						applyVisibleRange();
					}

					async function updateLatestCandle() {
						const resp = await (await fetch(klineUrl(INTERVAL, 2))).json();
						const klines = resp.result || [];
						if (!klines.length) return;
						const updated = toCandle(klines[0]);
						if (realCandles.length && realCandles[realCandles.length - 1].time === updated.time) {
							realCandles[realCandles.length - 1] = updated;
						} else {
							realCandles.push(updated);
						}
						rebuildSeriesData();
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
					}

					// Keeps the bold instrument-name label after "Settings" in
					// sync with whichever instrument is actually driving the
					// 4 gamma legs right now — INSTRUMENT (fixed by the URL
					// on /<instrument>/4l) takes priority, same precedence
					// fourLegGammaUrl() uses; SELECTED_INSTRUMENT otherwise
					// (the "Expiry" dropdown's own current choice, /4l/<asset>
					// only). On /<instrument>/4l this is redundant with the
					// template's own server-rendered t-esc="instrument" (the
					// span already shows the right text before this ever
					// runs) but harmless to call regardless.
					function updateInstrumentLabel() {
						document.getElementById('instrument-label').textContent = INSTRUMENT || SELECTED_INSTRUMENT || '';
					}

					async function setExpiry(instr) {
						SELECTED_INSTRUMENT = instr;
						updateInstrumentLabel();
						await refreshFourLegGamma();
						await refreshAvgGammaN1();
					}

					// Populates the "Expiry" dropdown from every currently
					// active (non-expired) instrument for ASSET — see
					// /api/expiries/<asset> and the SELECTED_INSTRUMENT
					// comment above. Selects the nearest (first, soonest)
					// entry by default. No-op on /<instrument>/4l (no
					// "Expiry" dropdown/#expiry-select element there at
					// all, since the instrument is already fixed by the
					// URL). Called once from init(), before the first
					// refreshFourLegGamma()/refreshAvgGammaN1() call, so
					// SELECTED_INSTRUMENT/NEAREST_INSTRUMENT are resolved
					// before either needs them.
					async function loadExpiries() {
						const select = document.getElementById('expiry-select');
						if (!select) return;
						const data = await (await fetch('/api/expiries/' + ASSET)).json();
						const expiries = data.expiries || [];
						select.innerHTML = '';
						expiries.forEach(instr => {
							const opt = document.createElement('option');
							opt.value = instr;
							opt.textContent = instr;
							select.appendChild(opt);
						});
						NEAREST_INSTRUMENT = expiries.length ? expiries[0] : null;
						SELECTED_INSTRUMENT = NEAREST_INSTRUMENT;
						if (SELECTED_INSTRUMENT) select.value = SELECTED_INSTRUMENT;
						updateInstrumentLabel();
					}

					async function setWindow(hours) {
						WINDOW_HOURS = (hours === 'all' || hours === 'midnight' || hours === 'auto') ? hours : parseInt(hours, 10);
						autoResolvedHours = null;
						await refreshFourLegGamma();
						setStatus(statusText());
					}

					// Rounds and abbreviates large raw dollar-gamma values
					// (hundreds of millions to billions is typical here) —
					// thousands as K, millions as M, sign preserved (long
					// legs' gamma is positive, short legs' is negative, per
					// this addon's own convention — see per_leg_greeks).
					function formatAbbreviated(value) {
						const sign = value < 0 ? '-' : '';
						const abs = Math.abs(value);
						if (abs >= 1e6) return sign + Math.round(abs / 1e6).toLocaleString('en-US') + 'M';
						if (abs >= 1e3) return sign + Math.round(abs / 1e3).toLocaleString('en-US') + 'K';
						return sign + Math.round(abs).toLocaleString('en-US');
					}

					// Only the LATEST persisted row is used — /api/four-leg-gamma
					// still returns the full history (unchanged backend), this
					// page just draws a horizontal line at each leg's own
					// current value instead of the whole time series.
					//
					// Shows #spinner for the duration of the fetch — this
					// endpoint recomputes the 4-leg gamma curve fresh
					// server-side on every call (no persisted history behind
					// this page), so it can take noticeably longer than the
					// plain klines poll. Hidden in a finally so a fetch
					// error still clears it rather than leaving it spinning
					// forever — same pattern the /gt page's own
					// refreshGammaTriple() uses.
					async function refreshFourLegGamma() {
						showSpinner();
						try {
							const data = await (await fetch(fourLegGammaUrl())).json();
							const points = data.points || [];
							const latest = points.length ? points[points.length - 1] : null;

							// Server-resolved window in hours (always present,
							// even with zero points) — only meaningful for
							// display while WINDOW_HOURS === 'auto', see
							// windowLabel()/hoursLabel() above.
							autoResolvedHours = typeof data.window_hours === 'number' ? data.window_hours : null;

							// 0 (not null) once resolved with no trades at all in
							// the current Window/Expiry — null only ever means
							// "haven't fetched yet", so tradeCountSuffix() can
							// tell "0 trades" apart from "not loaded".
							tradeCount = latest ? latest.trade_count : 0;
							setStatus(statusText());

							if (bcgPriceLine) { series.removePriceLine(bcgPriceLine); bcgPriceLine = null; }
							if (bpgPriceLine) { series.removePriceLine(bpgPriceLine); bpgPriceLine = null; }
							if (scgPriceLine) { series.removePriceLine(scgPriceLine); scgPriceLine = null; }
							if (spgPriceLine) { series.removePriceLine(spgPriceLine); spgPriceLine = null; }
							if (avgGammaPriceLine) { series.removePriceLine(avgGammaPriceLine); avgGammaPriceLine = null; }
							if (!latest) {
								return;
							}

							// 0.0 means absent (same convention every gamma_band/
							// smart_liq_*_price field in this addon uses) — no
							// line drawn rather than a spurious price-0 line.
							// axisLabelColor matches each line's own color here
							// (unlike most other price lines in this addon, which
							// force a black axis label regardless of line color)
							// so the label is identifiable by color at a glance
							// with 4 lines on one chart. Colors come from
							// chartColors (user-configurable via the "Settings"
							// button/dankbit_4l_chart_colors — see above), not a
							// theme-reactive axisBlack()/fixed constant.
							if (latest.bcg_price) {
								bcgPriceLine = series.createPriceLine({
									price: latest.bcg_price, color: chartColors.bcg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.bcg,
									title: 'LC ' + formatAbbreviated(latest.bcg_value),
								});
							}
							if (latest.bpg_price) {
								bpgPriceLine = series.createPriceLine({
									price: latest.bpg_price, color: chartColors.bpg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.bpg,
									title: 'LP ' + formatAbbreviated(latest.bpg_value),
								});
							}
							// Smart Liquidity — |LC value| + |SC value| (resp. |LP| +
							// |SP| for puts), a combined call-side/put-side gamma
							// magnitude appended to the SC/SP label after a "|",
							// purely a client-side display derivation off the same
							// 4 values these lines already carry (no server field
							// of its own, no relation to this addon's other,
							// differently-defined "Smart Liquidity" — see
							// forecast.smart_synthetic_liquidity()).
							if (latest.scg_price) {
								const smartLiqCall = Math.abs(latest.bcg_value) + Math.abs(latest.scg_value);
								scgPriceLine = series.createPriceLine({
									price: latest.scg_price, color: chartColors.scg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.scg,
									title: 'SC ' + formatAbbreviated(latest.scg_value) + ' | ' + formatAbbreviated(smartLiqCall),
								});
							}
							if (latest.spg_price) {
								const smartLiqPut = Math.abs(latest.bpg_value) + Math.abs(latest.spg_value);
								spgPriceLine = series.createPriceLine({
									price: latest.spg_price, color: chartColors.spg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.spg,
									title: 'SP ' + formatAbbreviated(latest.spg_value) + ' | ' + formatAbbreviated(smartLiqPut),
								});
							}
							// Average of the legs' own gamma PRICE levels (not their
							// gamma value) — over whichever legs are actually present
							// (0.0 means absent, same convention as the 4 lines
							// above), not a fixed /4, since dividing a partial sum
							// by 4 would silently skew the average toward 0 for
							// every missing leg. Skipped entirely when none of the
							// 4 are present. The label additionally shows the
							// average of those same legs' own gamma VALUES (paired
							// with price so both are averaged over the identical
							// present-leg set), same formatAbbreviated() the other
							// 4 lines already use for their own value.
							const gammaLegs = [
								{ price: latest.bcg_price, value: latest.bcg_value },
								{ price: latest.bpg_price, value: latest.bpg_value },
								{ price: latest.scg_price, value: latest.scg_value },
								{ price: latest.spg_price, value: latest.spg_value },
							].filter(leg => leg.price);
							if (gammaLegs.length) {
								const avgGammaPrice = gammaLegs.reduce((a, leg) => a + leg.price, 0) / gammaLegs.length;
								const avgGammaValue = gammaLegs.reduce((a, leg) => a + leg.value, 0) / gammaLegs.length;
								avgGammaPriceLine = series.createPriceLine({
									price: avgGammaPrice, color: AVG_GAMMA_COLOR, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Dashed,
									axisLabelVisible: true, axisLabelColor: AVG_GAMMA_COLOR,
									title: 'AVG ' + formatAbbreviated(avgGammaValue),
								});
							}
						} finally {
							hideSpinner();
						}
					}

					// Forward-looking reference for the expiry right after
					// whichever one this page is currently showing — see
					// AVG_GAMMA_N1_COLOR above. Always drawn over that
					// resolved expiry's FULL trade history (&amp;hours=all),
					// independent of this page's own Window selection, so
					// it stays a stable reference rather than
					// thinning out/disappearing along with a short
					// trailing window. Two different resolutions depending
					// on page mode:
					//  - /4l/&lt;asset&gt; (INSTRUMENT unset): only drawn while
					//    the "Expiry" dropdown's current selection is the
					//    nearest active expiry (SELECTED_INSTRUMENT ===
					//    NEAREST_INSTRUMENT), resolving Nearest+1 via the
					//    same ordinal endpoint the dropdown used to offer
					//    directly (?expiry=nearest_plus_1).
					//  - /&lt;instrument&gt;/4l (INSTRUMENT set, no "Expiry"
					//    dropdown/"Nearest" concept at all — the
					//    instrument is fixed by the URL): drawn
					//    unconditionally, resolving the expiry immediately
					//    after INSTRUMENT's own expiration instead
					//    (?after_instrument=&lt;INSTRUMENT&gt;) — server-side,
					//    since only the DB knows which expiry comes next
					//    after an arbitrary instrument (see
					//    four_leg_gamma_json's own docstring).
					// Removes its own previous line first, so switching
					// Expiry away from the nearest expiry (on
					// /4l/&lt;asset&gt;), or a failed/empty fetch (e.g.
					// INSTRUMENT is already the last active expiry,
					// nothing after it), never leaves a stale line drawn.
					async function refreshAvgGammaN1() {
						if (avgGammaN1PriceLine) { series.removePriceLine(avgGammaN1PriceLine); avgGammaN1PriceLine = null; }
						let url;
						if (INSTRUMENT) {
							url = '/api/four-leg-gamma/' + ASSET + '?after_instrument=' + INSTRUMENT + '&hours=all';
						} else if (SELECTED_INSTRUMENT && SELECTED_INSTRUMENT === NEAREST_INSTRUMENT) {
							url = '/api/four-leg-gamma/' + ASSET + '?expiry=nearest_plus_1&hours=all';
						} else {
							return;
						}
						const data = await (await fetch(url)).json();
						const points = data.points || [];
						const latest = points.length ? points[points.length - 1] : null;
						if (!latest) return;
						const legs = [
							{ price: latest.bcg_price, value: latest.bcg_value },
							{ price: latest.bpg_price, value: latest.bpg_value },
							{ price: latest.scg_price, value: latest.scg_value },
							{ price: latest.spg_price, value: latest.spg_value },
						].filter(leg => leg.price);
						if (!legs.length) return;
						const avgPrice = legs.reduce((a, leg) => a + leg.price, 0) / legs.length;
						const avgValue = legs.reduce((a, leg) => a + leg.value, 0) / legs.length;
						avgGammaN1PriceLine = series.createPriceLine({
							price: avgPrice, color: AVG_GAMMA_N1_COLOR, lineWidth: 2,
							lineStyle: LightweightCharts.LineStyle.Dotted,
							axisLabelVisible: true, axisLabelColor: AVG_GAMMA_N1_COLOR,
							title: (INSTRUMENT ? 'AVG NEXT ' : 'AVG N+1 ') + formatAbbreviated(avgValue),
						});
					}

					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
					}

					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
					}

					// "Settings" modal — see COLOR_STORAGE_KEY/DEFAULT_COLORS/
					// chartColors above. Unlike the Delta Chart's own version
					// of these 4 functions (which call applyOptions() on
					// already-created, persistent line series), this page's 4
					// gamma lines are plain createPriceLine()s recreated fresh
					// on every refreshFourLegGamma() call — there's no series
					// object to restyle in place, so Save/Reset just trigger
					// an immediate redraw instead.
					function openSettingsModal() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						document.getElementById('settings-modal').style.display = 'flex';
					}

					function closeSettingsModal() {
						document.getElementById('settings-modal').style.display = 'none';
					}

					function saveChartColors() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) chartColors[key] = input.value;
						});
						localStorage.setItem(COLOR_STORAGE_KEY, JSON.stringify(chartColors));
						refreshFourLegGamma();
						closeSettingsModal();
					}

					function resetChartColors() {
						chartColors = Object.assign({}, DEFAULT_COLORS);
						localStorage.removeItem(COLOR_STORAGE_KEY);
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						refreshFourLegGamma();
					}

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];

					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}

					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					async function init() {
						try {
							await loadCandles();
							await loadExpiries();
							await refreshFourLegGamma();
							await refreshAvgGammaN1();
							await refreshLastTrade();
							setStatus(statusText());
						}
						catch (e) { setStatus('Error: ' + e.message); }
					}
					init();
					setInterval(updateLatestCandle, 5000);
					// Every "Expiry" option now isolates to a single
					// instrument (see SELECTED_INSTRUMENT above) — no more
					// cumulative "all expiries at once" mode to skip polling
					// for, so this always refreshes. refreshAvgGammaN1() is
					// cheap to call unconditionally every tick — it no-ops
					// (just clears its own line) whenever the current
					// selection isn't the nearest expiry.
					setInterval(() => {
						refreshFourLegGamma();
						refreshAvgGammaN1();
					}, REFRESH);
					setInterval(refreshLastTrade, REFRESH);
				//
